import{z as s,x as l,o as A,c as p,q as n,j as r,D as a,d as e,s as i,S as t,b as B}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"电力市场设计","description":"","frontmatter":{"title":"电力市场设计","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/env-power-markets.md","filePath":"econ/env-power-markets.md","lastUpdated":1791063341000}'),d={name:"econ/env-power-markets.md"};function m(C,E,D,c,h,f){const o=l("Mermaid");return A(),p("div",null,[E[2]||(E[2]=n('<h1 id="电力市场设计" tabindex="-1">电力市场设计 <a class="header-anchor" href="#电力市场设计" aria-label="Permalink to &quot;电力市场设计&quot;">​</a></h1><div class="epigraph"><p>电力被物理绑在瞬时平衡与网络约束上：市场设计的任务不是给电定价，而是给「即时、就地、随时可调」分别定价。</p><footer>—— 据 Schweppe 等《Spot Pricing of Electricity》1988；Wilson, Econometrica, 2002 整理</footer></div><p><a href="/econ/env-energy-transition">上一课</a>把风光成本沿学习曲线打到平价，却留了一句：LCOE 便宜不等于系统便宜。本课把电网当成受物理约束的市场来解剖——电几乎不可大规模储存、频率必须实时平衡、潮流沿网络定律走——三个物理事实决定价格该怎么出、还缺什么产品。转型改变的不是电的物理，而是净负荷的形状：市场设计必须跟着重写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>现货电价不是普通商品价格：每个节点、每一小时都可能是一个独立市场。缺口三个。其一，missing money：峰机一年只有几百小时出清，若能量价格停在平均成本附近，容量投资的钱在能量市场里收不回来——投资信号缺一块。其二，波动电源重塑净负荷：午间光伏把净负荷压出深谷、日落后爬坡陡增（鸭式曲线），系统缺的不再是「发电量」而是「随叫随到的灵活性」，而灵活性在传统产品表里没有价签。其三，稀缺定价的政治脆弱：价格尖峰正是容量回收的机制，但 2000—01 年加州危机之后各地压低价格帽，等于亲手砍断自己需要的投资信号。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三件套。节点边际电价（LMP）：按边际机组出清，阻塞时节点价差出现，输电约束被写进价格；金融输电权与差价合约把位置风险变成可对冲的金融品——现货定价口径来自 Schweppe 等 1988，Wilson 2002 把整个架构写成协调问题。双结算：日前市场锁量锁价，实时市场只平衡偏差，预测误差单独定价。资源充裕度两条路线：能量-only（ERCOT 把能量价格帽放到失负荷价值 VOLL 的数量级，9000 美元/MWh）让稀缺电价养容量；或容量市场（PJM）拍卖「可用容量」直接给钱。灵活性产品化：调频、爬坡、备用逐个开列产品，把「随时可调」标成可交易品。</p>',7)),(A(),r(t,null,{default:a(()=>[i(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20PHYS%5B%22%E7%89%A9%E7%90%86%3A%20%E7%9E%AC%E6%97%B6%E5%B9%B3%E8%A1%A1%20%2B%20%E7%BD%91%E7%BB%9C%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20LMP%5B%22%E8%8A%82%E7%82%B9%E8%BE%B9%E9%99%85%E7%94%B5%E4%BB%B7%20LMP%22%5D%0A%20%20LMP%20--%3E%20DA%5B%22%E6%97%A5%E5%89%8D%3A%20%E9%94%81%E9%87%8F%E9%94%81%E4%BB%B7%22%5D%0A%20%20LMP%20--%3E%20RT%5B%22%E5%AE%9E%E6%97%B6%3A%20%E5%B9%B3%E8%A1%A1%E5%81%8F%E5%B7%AE%22%5D%0A%20%20DUCK%5B%22%E6%B3%A2%E5%8A%A8%E7%94%B5%E6%BA%90%3A%20%E5%87%80%E8%B4%9F%E8%8D%B7%E5%8F%98%E5%BD%A2%22%5D%20--%3E%20FLEX%5B%22%E8%BE%85%E5%8A%A9%E6%9C%8D%E5%8A%A1%3A%20%E8%B0%83%E9%A2%91%E4%B8%8E%E7%88%AC%E5%9D%A1%22%5D%0A%20%20MISS%5B%22missing%20money%22%5D%20--%3E%20CHOICE%7B%22%E5%85%85%E8%A3%95%E5%BA%A6%E8%B7%AF%E7%BA%BF%22%7D%0A%20%20CHOICE%20--%3E%7C%E8%83%BD%E9%87%8F-only%7C%20VOLL%5B%22%E7%A8%80%E7%BC%BA%E7%94%B5%E4%BB%B7%20%2B%20%E9%AB%98%E4%BB%B7%E5%B8%BD%22%5D%0A%20%20CHOICE%20--%3E%7C%E5%AE%B9%E9%87%8F%E5%B8%82%E5%9C%BA%7C%20CAPA%5B%22%E5%AE%B9%E9%87%8F%E6%8B%8D%E5%8D%96%E7%BB%99%E9%92%B1%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("p",null,[B("span",{class:"marginnote"},"「鸭式曲线」是把净负荷（总用电减去风光出力）画成曲线：中午光伏把肚子压出一个深谷，日落后光伏归零、净负荷猛地抬头，像一只鸭子的脖子。系统这时缺的不是「发了多少度电」，而是在两三个小时内调动几十吉瓦爬坡的能力——这正是灵活性产品要标价的东西。")],-1)),E[4]||(E[4]=B("h2",{id:"机制",tabindex:"-1"},[e("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=B("p",null,[e("稀缺电价为什么是可靠性的价格形态：可靠性是电网内的公共品——谁都享受不停电、无法排除搭便车者（"),B("a",{href:"/econ/public-goods"},"公共物品"),e("的题内之义）；稀缺电价把「不停电的边际价值」写回能量价格，砍掉它，容量投资只剩行政目标，市场退化成计划。碳价与电力市场为什么是叠加而非并列：ETS 抬高化石机组的边际成本，merit order 重排；上一课的近零边际成本电源进一步压低出清价——missing money 加重、峰谷价差重排，转型直接改写市场设计参数，这是两门课的接口。价帽压太低为什么必然换来非价格配给：出清改由滚动停电完成，稀缺以最贵的方式回到系统。")],-1)),(A(),r(t,null,{default:a(()=>[i(o,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20REN%5B%22%E9%A3%8E%E5%85%89%3A%20%E8%BF%91%E9%9B%B6%E8%BE%B9%E9%99%85%E6%88%90%E6%9C%AC%22%5D%20--%3E%20MO%5B%22merit%20order%20%E9%87%8D%E6%8E%92%22%5D%0A%20%20CARBON%5B%22%E7%A2%B3%E4%BB%B7%20ETS%22%5D%20--%3E%20FOSSIL%5B%22%E5%8C%96%E7%9F%B3%E6%9C%BA%E7%BB%84%E8%BE%B9%E9%99%85%E6%88%90%E6%9C%AC%E6%8A%AC%E5%8D%87%22%5D%0A%20%20FOSSIL%20--%3E%20MO%0A%20%20MO%20--%3E%20CLEAR%5B%22%E5%87%BA%E6%B8%85%E4%BB%B7%E8%A2%AB%E5%8E%8B%E4%BD%8E%22%5D%0A%20%20CLEAR%20--%3E%20MM%5B%22missing%20money%20%E5%8A%A0%E9%87%8D%22%5D%0A%20%20MM%20--%3E%20WEAK%5B%22%E5%AE%B9%E9%87%8F%E6%8A%95%E8%B5%84%E4%BF%A1%E5%8F%B7%E6%9B%B4%E5%BC%B1%22%5D%0A%20%20WEAK%20--%3E%20FIX%7B%22%E8%A1%A5%E6%95%91%E8%B7%AF%E7%BA%BF%22%7D%0A%20%20FIX%20--%3E%7C%E7%A8%80%E7%BC%BA%E7%94%B5%E4%BB%B7%7C%20SPIKE%5B%22%E6%9B%B4%E6%B7%B1%E6%9B%B4%E5%B0%96%E7%9A%84%E4%BB%B7%E6%A0%BC%E5%B3%B0%22%5D%0A%20%20FIX%20--%3E%7C%E5%AE%B9%E9%87%8F%E6%9C%BA%E5%88%B6%7C%20SUB%5B%22%E5%AE%B9%E9%87%8F%E6%8B%8D%E5%8D%96%E7%9B%B4%E6%8E%A5%E7%BB%99%E9%92%B1%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=n('<p><span class="marginnote">missing money 的算术：一台年固定成本 100 万美元的峰机，若一年只在 100 个稀缺小时出清，每小时需回收 1 万美元/MWh 才够本；若价格帽压到 500 美元，一年最多收 5 万美元，九成半投资没有着落——缺口不会消失，只会换个地方要钱。</span></p><p><span class="marginnote">初学者容易以为压低价格帽能保护消费者。实际上尖峰电价一年只占几十小时，压帽省下的电费远小于后果：容量靠行政补贴维持（纳税人付）、缺额靠滚动停电配给（全社会付）——稀缺不会因为不许标价就消失。</span></p><p><span class="marginnote">同一台燃气峰机，在 9000 美元/MWh 帽下靠稀缺小时回收投资，在低帽下靠容量拍卖拿钱——ERCOT 与 PJM 的路线之争，本质是「信价格」还是「信行政目标」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>容量市场可能双重支付，也常被批评为给本该退出的旧机组续命——拍卖设计决定它是保险还是福利。节点定价在阻塞严重的区域制造本地市场势力；分区定价简化了结算，却把阻塞成本摊平、误导选址。价格尖峰的公平问题应交给配电价与定向转移处理，而不是压帽价。配电侧的分布式资源、储能与需求响应正在改写产品表，本课停在批发侧。跨区互联与市场耦合解决一部分平衡问题，但政策的国境线是另一回事——碳政策的边界漏洞，下一课的题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>物理三事实（瞬时平衡、网络约束、难储存）是市场设计的一阶输入，不是摩擦。</li><li>LMP 把阻塞写进价格，双结算分离预测误差，金融衍生品管位置与价格风险。</li><li>missing money 是能量市场的结构性缺口：能量-only 靠稀缺价帽，容量市场靠拍卖给钱。</li><li>可靠性是公共品，稀缺电价与容量机制是它的两种定价形态；压帽价换来停电配给。</li><li>碳价与波动电源通过 merit order 与出清价改写设计参数，转型与市场设计互相推进。</li><li>出处：Schweppe 等 1988；Wilson 2002；Joskow 2006。</li></ul>',7))])}const P=s(d,[["render",m]]);export{F as __pageData,P as default};
